from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            comp = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); comp.add((yy,xx)); q.append((yy,xx))
            comps.append(comp)
    if not comps:
        return [row[:] for row in grid]
    template = max(comps, key=len)
    r0, r1 = min(r for r,c in template), max(r for r,c in template)
    c0, c1 = min(c for r,c in template), max(c for r,c in template)
    targets = [next(iter(comp)) for comp in comps if comp is not template and len(comp) == 1]
    out = [row[:] for row in grid]
    dh, dw = r1-r0+1, c1-c0+1
    patch = [grid[r0+r][c0:c1+1] for r in range(dh)]
    for r,c in targets:
        top, left = r-dh//2, c-dw//2
        for dr in range(dh):
            for dc in range(dw):
                y,x=top+dr,left+dc
                if 0 <= y < h and 0 <= x < w:
                    out[y][x] = patch[dr][dc]
    return out

